  const deepClone = obj => JSON.parse(JSON.stringify(obj));
  function loadData() {
    try {
      const stored = JSON.parse(localStorage.getItem(STORAGE_KEY));
      if (!stored) return deepClone(defaultData);
      return {
        ...deepClone(defaultData), ...stored,
        settings:{...defaultData.settings,...(stored.settings||{})},
        products:stored.products || deepClone(defaultData.products), customers:stored.customers || deepClone(defaultData.customers),
        suppliers:stored.suppliers || deepClone(defaultData.suppliers), sales:stored.sales || deepClone(defaultData.sales),
        purchaseOrders:stored.purchaseOrders || deepClone(defaultData.purchaseOrders), expenses:stored.expenses || deepClone(defaultData.expenses),
        creditHistory:stored.creditHistory || deepClone(defaultData.creditHistory), resellers:stored.resellers || deepClone(defaultData.resellers),
        stockAdjustments:stored.stockAdjustments || deepClone(defaultData.stockAdjustments)
      };
    } catch { return deepClone(defaultData); }
  }

