  const dateText = value => value ? new Intl.DateTimeFormat('en-PH',{dateStyle:'medium'}).format(new Date(value)) : '-';
  const dateTimeText = value => value ? new Intl.DateTimeFormat('en-PH',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value)) : '-';
  const activeProducts = () => db.products.filter(p=>!p.archived);
  const archivedProducts = () => db.products.filter(p=>p.archived);
  const resellerQtyForProduct = id => (db.resellers||[]).reduce((sum,r)=>sum+(r.stock||[]).filter(x=>x.productId===id).reduce((a,x)=>a+Number(x.qty||0),0),0);
  const totalTrackedQty = p => Number(p.qty||0)+resellerQtyForProduct(p.id);
  const lowStock = () => activeProducts().filter(p=>p.qty>0 && p.qty<=Number(p.reorder||db.settings.lowStockThreshold));
  const outOfStock = () => db.products.filter(p=>totalTrackedQty(p)<=0);
  const supplierName = id => db.suppliers.find(s=>s.id===id)?.name || 'Not assigned';
  const customerName = id => db.customers.find(c=>c.id===id)?.name || 'Walk-in customer';
  const purchaseSourceName = order => order.sourceName || supplierName(order.supplierId) || 'Not recorded';
  const salesTotal = sales => sales.reduce((sum,s)=>sum+Number(s.total||0),0);
  const expensesTotal = list => list.reduce((sum,e)=>sum+Number(e.amount||0),0);
  const grossProfit = sales => sales.reduce((sum,s)=>sum+(s.items||[]).reduce((a,i)=>a+(Number(i.price)-Number(i.cost||0))*Number(i.qty),0)-Number(s.discount||0),0);
  const todaySales = () => db.sales.filter(s=>new Date(s.date).toDateString()===new Date().toDateString());
  const isOwner = () => !state.resellerPreviewId && (db.sessionRole||'owner')==='owner';
  const currentReseller = () => db.resellers.find(r=>r.id===(state.resellerPreviewId||db.activeResellerId)) || db.resellers[0];
  const resellerCustomers = r => r?.customers || [];
  const resellerExpenses = r => r?.expenses || [];
  const storeSales = () => db.sales.filter(s=>(s.channel||'Store')!=='Reseller');
  const resellerSales = r => db.sales.filter(s=>s.channel==='Reseller' && s.resellerId===r?.id);
  const resellerCustomerName = (r,id) => resellerCustomers(r).find(c=>c.id===id)?.name || 'Walk-in customer';
  const resellerCreditTotal = r => resellerCustomers(r).reduce((a,c)=>a+Number(c.creditBalance||0),0);
  const resellerSalesTotal = r => salesTotal(resellerSales(r));
  const resellerProfit = r => resellerSales(r).reduce((sum,s)=>sum+(s.items||[]).reduce((a,i)=>a+(Number(i.price)-Number(i.resellerCost||i.cost||0))*Number(i.qty),0)-Number(s.discount||0),0)-expensesTotal(resellerExpenses(r));
  const resellerPaymentMethods = r => ['Cash','GCash','Credit'].filter(m=>r?.paymentMethods?.[m]!==false);
  const resellerStockEntry = (r,productId) => (r?.stock||[]).find(x=>x.productId===productId);
  const resellerAvailableQty = (r,productId) => Number(resellerStockEntry(r,productId)?.qty||0);
  const resellerArrangement = r => r?.arrangement==='Wholesale'?'Wholesale':'Consignment';
  const resellerPendingCount = r => [...(r?.stockIssues||[]),...(r?.returnRequests||[])].filter(x=>x.status==='Pending').length;
  const resellerOutstandingQty = r => (r?.stock||[]).reduce((a,x)=>a+Number(x.qty||0),0);
  const resellerStockValue = r => (r?.stock||[]).reduce((a,x)=>a+Number(x.qty||0)*Number(x.resellerCost||x.resellerPrice||0),0);
  const productMode = p => { if(!db.settings.enableBatchTracking) return 'simple'; return (p.inventoryMode && p.inventoryMode!=='default') ? p.inventoryMode : (db.settings.inventoryDefault||'simple'); };
  const soonestExpiration = p => {
    if (!db.settings.enableExpirationTracking || p.trackExpiration===false) return '';
    if (productMode(p)==='batch' && Array.isArray(p.batches)) {
      const dates=p.batches.filter(b=>Number(b.qtyRemaining)>0&&b.expiration).map(b=>b.expiration).sort();
      if(dates.length)return dates[0];
    }
    return p.expiration||'';
  };
  const isExpiringSoon = p => {const d=soonestExpiration(p);return !!d && new Date(d)<=new Date(Date.now()+Number(db.settings.expiryAlertDays||3)*86400000);};
  const withinDate = (value,start,end) => {
    const d = new Date(value); d.setHours(0,0,0,0);
    if (start && d < new Date(`${start}T00:00:00`)) return false;
    if (end && d > new Date(`${end}T23:59:59`)) return false;
    return true;
  };
  const reportRange = () => {
    if(state.reportPeriod==='all') return ['', ''];
    if(state.reportPeriod==='custom') return [state.reportStart,state.reportEnd];
    const end=isoDate(), d=new Date();
    if(state.reportPeriod==='today') return [end,end];
    if(state.reportPeriod==='week'){d.setDate(d.getDate()-6);return [d.toISOString().slice(0,10),end];}
    d.setDate(1);return [d.toISOString().slice(0,10),end];
  };
  function archiveIfOutOfStock(product, reason='Automatically archived because all tracked stock reached zero') {
    if (!product || totalTrackedQty(product)>0) return false;
    product.qty=0;
    product.archived=true;
    product.archiveReason=reason;
    product.archivedAt=product.archivedAt || nowISO();
    product.stockHistory=product.stockHistory || [];
    product.stockHistory.push({date:product.archivedAt,type:'Auto-archived',quantity:0,note:reason});
    return true;
  }
  function deductFifo(product, qty) {
    if(productMode(product)!=='batch' || !Array.isArray(product.batches)) return;
    let remaining=Number(qty);
    const batches=product.batches.filter(b=>Number(b.qtyRemaining)>0).sort((a,b)=>new Date(a.dateReceived)-new Date(b.dateReceived));
    for(const b of batches){if(remaining<=0)break;const used=Math.min(remaining,Number(b.qtyRemaining));b.qtyRemaining-=used;remaining-=used;}
  }
  function addStockAdjustment(product, quantity, reason, note='', source='Store', date=nowISO()) {
    const q=Number(quantity); if(!q)return;
    db.stockAdjustments=db.stockAdjustments||[];
    db.stockAdjustments.push({id:`ADJ-${1001+db.stockAdjustments.length}`,date,productId:product.id,productName:product.name,quantity:q,reason,note,source});
    product.stockHistory=product.stockHistory||[];
    product.stockHistory.push({date,type:'Stock adjustment',quantity:q,note:`${reason}${note?`: ${note}`:''}`});
  }
  function applyPreferences() {
    const theme=db.settings.theme==='dark'?'dark':'light';
    const preview=db.settings.previewMode==='mobile'?'mobile':'desktop';
    document.documentElement.dataset.theme=theme;
    document.body.classList.toggle('demo-mobile-preview',preview==='mobile' && db.loggedIn && !['landing','login','signup','forgot'].includes(state.view));
    document.querySelector('meta[name="theme-color"]')?.setAttribute('content',theme==='dark'?'#27312d':'#176b4d');
  }
  function normalizeData() {
    db.resellers=db.resellers||[]; db.stockAdjustments=db.stockAdjustments||[];
    db.products.forEach(p=>{p.stockHistory=p.stockHistory||[];p.batches=p.batches||[];if(p.trackExpiration===undefined)p.trackExpiration=!!p.expiration;if(!p.inventoryMode)p.inventoryMode='default';if(totalTrackedQty(p)<=0)archiveIfOutOfStock(p,p.archiveReason||'Automatically archived because all tracked stock reached zero');});
    db.purchaseOrders.forEach(o=>{o.sourceType=o.sourceType||'Supplier delivery';o.sourceName=o.sourceName||supplierName(o.supplierId);});
    db.customers.forEach(c=>{c.transactions=c.transactions||[];if(!Number.isInteger(c.creditCycleStartIndex))c.creditCycleStartIndex=0;});
    db.resellers.forEach(r=>{
      r.stock=r.stock||[];r.transactions=r.transactions||[];r.payments=r.payments||[];r.balance=Number(r.balance||0);r.arrangement=r.arrangement||'Consignment';r.paymentMethods={Cash:true,GCash:true,Credit:true,...(r.paymentMethods||{})};r.notificationMode=r.notificationMode||'grouped';r.customers=r.customers||[];r.creditHistory=r.creditHistory||[];r.expenses=r.expenses||[];r.stockIssues=r.stockIssues||[];r.returnRequests=r.returnRequests||[];r.preferences={notifyCustomerCredit:true,notifyLowStock:true,notifyExpiry:true,...(r.preferences||{})};
      r.customers.forEach(c=>{c.transactions=c.transactions||[];if(!Number.isInteger(c.creditCycleStartIndex))c.creditCycleStartIndex=0;});
      r.stock.forEach(x=>{x.resellerCost=Number(x.resellerCost??x.resellerPrice??0);x.minimumPrice=Number(x.minimumPrice??x.resellerPrice??0);x.lastSellingPrice=Number(x.lastSellingPrice??x.minimumPrice);x.pendingReturnQty=Number(x.pendingReturnQty||0);x.pendingIssueQty=Number(x.pendingIssueQty||0);});
    });
    db.expenses.forEach(e=>{e.paymentMethod=e.paymentMethod||'Cash';});
    db.creditHistory=db.creditHistory||[];
    db.settings.resellerSaleNotificationMode=db.settings.resellerSaleNotificationMode||'grouped';
    if(db.settings.showResellerProfit===undefined)db.settings.showResellerProfit=false;
  }

  normalizeData();
  save();

