  function statusFor(p) {
    if (p.archived) return ['Archived','danger'];
    if (db.settings.enableResellers && Number(p.qty)<=0 && resellerQtyForProduct(p.id)>0) return ['With Resellers','info'];
    if (!db.settings.enableResellers && Number(p.qty)<=0) return ['Out of Stock','danger'];
    if (totalTrackedQty(p)<=0) return ['Out of Stock','danger'];
    if (Number(p.qty)<=Number(p.reorder||db.settings.lowStockThreshold)) return ['Low Stock','warning'];
    if (isExpiringSoon(p)) return ['Expiring Soon','purple'];
    return ['In Stock','success'];
  }
