      return `${pageHead('Reports','A simplified view of only your reseller operation.',`<button class="btn btn-secondary" data-action="export-excel">${icon('download')} Excel</button><button class="btn btn-secondary" data-action="export-pdf">${icon('print')} PDF</button>`)}<div class="period-pills">${[['today','Today'],['week','This Week'],['month','This Month'],['all','All Time'],['custom','Custom']].map(([v,l])=>`<button class="payment-pill ${state.reportPeriod===v?'active':''}" data-action="report-period" data-value="${v}">${l}</button>`).join('')}</div>${state.reportPeriod==='custom'?`<div class="date-filters section-gap"><div class="field"><label>From</label><input class="input" type="date" id="reportStart" value="${state.reportStart}"></div><div class="field"><label>To</label><input class="input" type="date" id="reportEnd" value="${state.reportEnd}"></div></div>`:''}<div class="report-grid section-gap">${statCard('sales','Total sales',money(revenue))}${statCard('peso','Estimated profit',money(profit),'',profit>=0?'green':'red')}${statCard('expenses','Expenses',money(exp))}${statCard('receipt','Transactions',sales.length)}</div><div class="row-between section-gap"><div><h2 class="section-title">Detailed reports</h2><p class="muted">Only your own sales, stock, customers, expenses, and profit are included.</p></div><button class="btn btn-secondary" data-action="toggle-report-details">${state.reportDetails?'Hide details':'View Detailed Reports'}</button></div>${state.reportDetails?`<div class="report-toolbar"><div class="report-tabs">${types.map(([v,l])=>`<button class="tab-button ${state.reportType===v?'active':''}" data-action="report-type" data-value="${v}">${l}</button>`).join('')}</div></div>${body}`:''}`;
