    const allSales=db.sales.filter(s=>withinDate(s.date,start,end)),storePeriodSales=allSales.filter(s=>(s.channel||'Store')!=='Reseller'),resellerPeriodSales=db.settings.enableResellers?allSales.filter(s=>s.channel==='Reseller'):[],visibleSales=db.settings.enableResellers?allSales:storePeriodSales,expenses=db.expenses.filter(e=>withinDate(e.date,start,end)),orders=db.purchaseOrders.filter(o=>withinDate(o.dateReceived,start,end)),revenue=salesTotal(storePeriodSales),resellerRevenue=salesTotal(resellerPeriodSales),cogs=storePeriodSales.reduce((a,s)=>a+(s.items||[]).reduce((x,i)=>x+Number(i.cost||0)*Number(i.qty),0),0),exp=expensesTotal(expenses),net=revenue-cogs-exp;
    const reportTypes=[['sales','Sales'],['inventory','Inventory'],['profit','Profit / loss'],['credit','Customer credit'],['supplier','Supplier purchases']];if(db.settings.enableResellers)reportTypes.push(['reseller','Resellers']);
