      const list=isOwner()?db.customers:resellerCustomers(currentReseller());if(o.id){Object.assign(list.find(x=>x.id===o.id),{name:o.name,phone:o.phone,address:o.address});}else list.push({id:uid(isOwner()?'c':'rc'),name:o.name,phone:o.phone,address:o.address,creditBalance:0,dueDate:'',status:'Paid',transactions:[],creditCycleStartIndex:0});save();state.modal=null;render();toast('Customer saved.');
